#!/usr/bin/env python3
"""Tests for the pixf sidecar parser.

The byte layout here is the contract with the STB producer. The values in the
first test were taken from a real pixf box produced by stb_streamer, so a
change on either side fails here before it reaches a recording.
"""
import struct
import tempfile
import unittest
from pathlib import Path

import cm_features


def header(count, first_us=0, last_us=100000, video=1, audio=1,
           generation=7, dropped=0, schema=cm_features.SCHEMA, flags=0):
    return struct.pack('<HHIIqqIIII', schema, flags, generation, count,
                       first_us, last_us, video, audio, dropped, 0)


def video_record(pts_us, frame, mean_x100, black_x1000, scene_x100):
    return struct.pack('<BBHqIiII', 1, 0, 0, pts_us, frame, mean_x100, black_x1000, scene_x100)


def audio_record(pts_us, samples, rms_x100):
    return struct.pack('<BBHqIiII', 2, 0, 0, pts_us, samples, rms_x100, 0, 0)


class ParseTest(unittest.TestCase):

    def test_real_capture_values(self):
        # Generated by stb_streamer: lavfi.signalstats.YAVG=125.481,
        # blackframe.pblack=0.5, scd.score=12.34, astats RMS -21.06 dB.
        raw = header(2, 0, 0) + video_record(0, 0, 12548, 5, 1234) + audio_record(0, 1024, -2106)
        parsed = cm_features.parse(raw)
        self.assertEqual(parsed['meta']['video_rows'], 1)
        self.assertEqual(parsed['meta']['audio_rows'], 1)
        video = parsed['video'][0]
        self.assertAlmostEqual(video['mean'], 125.48, places=2)
        self.assertAlmostEqual(video['black_fraction'], 0.005, places=3)
        self.assertAlmostEqual(video['scene'], 12.34, places=2)
        audio = parsed['audio'][0]
        self.assertEqual(audio['samples'], 1024)
        self.assertAlmostEqual(audio['rms_db'], -21.06, places=2)

    def test_multiple_batches_concatenate(self):
        raw = (header(2, 0, 100000) + video_record(0, 0, 100, 0, 0) + audio_record(0, 1024, -2000)
               + header(2, 100000, 200000) + video_record(100000, 1, 100, 0, 0)
               + audio_record(21333, 1024, -2000))
        parsed = cm_features.parse(raw)
        self.assertEqual(len(parsed['video']), 2)
        self.assertEqual(len(parsed['audio']), 2)
        self.assertAlmostEqual(parsed['video'][1]['pts'], 0.1, places=3)

    def test_truncated_record_is_refused(self):
        raw = header(2) + video_record(0, 0, 100, 0, 0)      # second record missing
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'truncated'):
            cm_features.parse(raw)

    def test_unknown_schema_is_refused(self):
        raw = header(1, schema=9) + video_record(0, 0, 100, 0, 0)
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'schema'):
            cm_features.parse(raw)

    def test_reversed_pts_is_refused(self):
        raw = (header(3) + video_record(9000000, 1, 100, 0, 0)
               + video_record(0, 0, 100, 0, 0) + audio_record(0, 1024, -2000))
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'backwards'):
            cm_features.parse(raw)

    def test_missing_audio_is_refused(self):
        raw = header(1, audio=0) + video_record(0, 0, 100, 0, 0)
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'audio'):
            cm_features.parse(raw)

    def test_generation_change_is_a_gap_not_a_failure(self):
        # A pipeline restart bumps the generation and the timeline restarts.
        first = header(2, 0, 100000) + video_record(0, 0, 100, 0, 0) + audio_record(0, 1024, -2000)
        second = (struct.pack('<HHIIqqIIII', 1, 0, 99, 2, 0, 100000, 1, 1, 0, 0)
                  + video_record(0, 1, 100, 0, 0) + audio_record(0, 1024, -2000))
        parsed = cm_features.parse(first + second)
        self.assertEqual(len(parsed['video']), 2)
        self.assertEqual(parsed['meta']['generations'], 1)

    def test_black_intervals_become_black_frames(self):
        # Type 3 records carry blackdetect intervals; the rows inside them must
        # look like the black frames cm-scan would report.
        interval = struct.pack('<BBHqIiII', 3, 0, 0, 500000, 1000, 0, 0, 0)
        raw = (header(4, 0, 1000000, video=2, audio=1)
               + video_record(0, 0, 100, 0, 0) + video_record(700000, 1, 100, 0, 0)
               + audio_record(0, 1024, -2000) + interval)
        parsed = cm_features.parse(raw)
        self.assertEqual(parsed['video'][0]['black_fraction'], 0.0)
        self.assertEqual(parsed['video'][1]['black_fraction'], 1.0)

    def test_interleaved_video_and_audio_blocks_are_allowed(self):
        # One pixf batch carries the video rows first and the audio rows after
        # them, so the audio pts restarts lower than the last video pts.
        raw = (header(4, 0, 100000, video=2, audio=2)
               + video_record(0, 0, 100, 0, 0) + video_record(100000, 1, 100, 0, 0)
               + audio_record(0, 1024, -2000) + audio_record(21333, 1024, -2000))
        parsed = cm_features.parse(raw)
        self.assertEqual(len(parsed['video']), 2)
        self.assertEqual(len(parsed['audio']), 2)

    def test_out_of_range_rms_is_clamped(self):
        # A capture build that converted "-inf" to an integer sentinel.
        raw = (header(2) + video_record(0, 0, 100, 0, 0)
               + audio_record(0, 1024, -2147483648))
        parsed = cm_features.parse(raw)
        self.assertEqual(parsed['audio'][0]['rms_db'], -120.0)

    def test_unknown_record_type_is_refused(self):
        raw = header(2) + video_record(0, 0, 100, 0, 0) + struct.pack(
            '<BBHqIiII', 9, 0, 0, 0, 0, 0, 0, 0)
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'record type'):
            cm_features.parse(raw)

    def test_dropped_records_invalidate_the_sidecar(self):
        raw = header(2, dropped=3) + video_record(0, 0, 100, 0, 0) + audio_record(0, 1024, -2000)
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'dropped'):
            cm_features.load(self._write(raw), expected_duration=0)

    def test_short_coverage_is_refused(self):
        raw = header(2, 0, 100000) + video_record(0, 0, 100, 0, 0) + audio_record(0, 1024, -2000)
        path = self._write(raw)
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'cover'):
            cm_features.load(path, expected_duration=60.0)

    def test_sidecar_that_starts_early_is_accepted(self):
        # The tap runs before the recorder receives media; the extra lead is
        # harmless because only the shared window is compared.
        raw = (header(3, 0, 100_000_000, video=2)
               + video_record(0, 0, 100, 0, 0) + video_record(100_000_000, 1, 100, 0, 0)
               + audio_record(0, 1024, -2000))
        path = self._write(raw)
        parsed = cm_features.load(path, expected_duration=12.0)
        self.assertEqual(len(parsed['video']), 2)

    def test_missing_file_is_refused(self):
        with self.assertRaisesRegex(cm_features.FeatureUnavailable, 'cannot read'):
            cm_features.load('/nonexistent/features.bin')

    def _write(self, raw):
        handle = tempfile.NamedTemporaryFile(delete=False, suffix='.bin')
        handle.write(raw)
        handle.close()
        self.addCleanup(lambda: Path(handle.name).unlink(missing_ok=True))
        return handle.name


class CompareTest(unittest.TestCase):

    def test_identical_measurement_is_within_tolerance(self):
        provided = dict(video=[dict(pts=0.0, mean=100.0, scene=1.0),
                               dict(pts=0.1, mean=101.0, scene=2.0)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=0.0, mean=100.0, scene=1.0),
                    dict(pts=0.1, mean=101.0, scene=2.0)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertTrue(report['within_tolerance'])
        self.assertEqual(report['mean_luma_delta'], 0.0)

    def test_subsampled_capture_still_pairs_with_full_measurement(self):
        # The capture side samples every third frame; the NAS has all of them.
        # Values must still pair by time, not by exact timestamp.
        provided = dict(video=[dict(pts=0.0, mean=100.0, scene=1.0),
                               dict(pts=0.1, mean=100.0, scene=1.0),
                               dict(pts=0.2, mean=100.0, scene=1.0)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=0.0, mean=100.0, scene=1.0),
                    dict(pts=0.033, mean=100.0, scene=1.0),
                    dict(pts=0.067, mean=100.0, scene=1.0),
                    dict(pts=0.1, mean=100.0, scene=1.0)]
        report = cm_features.compare(provided, measured, [dict(pts=0.021, rms_db=-30.0)])
        self.assertEqual(report.get('video_matched'), 2)  # 0.0 and 0.1
        self.assertAlmostEqual(report['mean_luma_delta'], 0.0, places=3)

    def test_different_values_are_not_within_tolerance(self):
        # Same frames, different measurements: the sideband reported values the
        # NAS does not reproduce, so it must not be applied.
        provided = dict(video=[dict(pts=0.0, mean=140.0, scene=9.0),
                               dict(pts=1.0, mean=140.0, scene=9.0)],
                        audio=[dict(pts=0.0, rms_db=-20.0)])
        measured = [dict(pts=0.0, mean=100.0, scene=1.0),
                    dict(pts=1.0, mean=100.0, scene=1.0)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertFalse(report['within_tolerance'])
        self.assertAlmostEqual(report['luma_median_delta'], 40.0, places=3)

    def test_a_minority_of_bad_frames_does_not_decide_the_gate(self):
        # Most frames agree; a few are corrupt on the capture side.
        provided = dict(video=[dict(pts=i * 0.1, mean=100.0 + (90.0 if i < 2 else 0.0), scene=1.0)
                               for i in range(20)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=i * 0.1, mean=100.0, scene=1.0) for i in range(20)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertGreater(report['mean_luma_delta'], 2.0)
        self.assertLessEqual(report['luma_median_delta'], 2.0)
        self.assertLessEqual(report['luma_outlier_ratio'], 0.10)
        self.assertTrue(report['within_tolerance'])

    def test_systematic_luma_difference_is_rejected(self):
        provided = dict(video=[dict(pts=i * 0.1, mean=110.0, scene=1.0) for i in range(20)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=i * 0.1, mean=100.0, scene=1.0) for i in range(20)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertGreater(report['luma_median_delta'], 2.0)
        self.assertFalse(report['within_tolerance'])

    def test_scene_agreement_counts_threshold_matches(self):
        provided = dict(video=[dict(pts=0.0, mean=100.0, scene=20.0),
                               dict(pts=0.1, mean=100.0, scene=5.0)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=0.0, mean=100.0, scene=19.0),
                    dict(pts=0.1, mean=100.0, scene=4.0)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertEqual(report['scene_agreement'], 1.0)

    def test_scene_frames_on_the_wrong_side_fail_the_gate(self):
        # Every frame sits on the opposite side of the cut threshold.
        provided = dict(video=[dict(pts=t * 0.1, mean=100.0, scene=20.0) for t in range(20)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(20)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertLess(report['scene_agreement'], 0.90)
        self.assertFalse(report['within_tolerance'])

    def test_scene_agreement_detects_a_flip(self):
        provided = dict(video=[dict(pts=0.0, mean=100.0, scene=20.0),
                               dict(pts=1.0, mean=100.0, scene=20.0)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=0.0, mean=100.0, scene=5.0),
                    dict(pts=1.0, mean=100.0, scene=5.0)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertEqual(report['scene_agreement'], 0.0)

    def test_capture_before_the_media_is_clipped(self):
        # The tap starts a moment before the recorder receives media; only the
        # shared window is compared, so the extra rows do not fail the check.
        # The tap runs from before the media to after it; only the overlap counts.
        provided = dict(video=[dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(50)],
                        audio=[dict(pts=t * 0.1, rms_db=-30.0) for t in range(50)])
        measured = [dict(pts=2.0 + t * 0.1, mean=100.0, scene=1.0) for t in range(20)]
        report = cm_features.compare(provided, measured, [dict(pts=2.0 + t * 0.1, rms_db=-30.0) for t in range(20)])
        self.assertEqual(report['window'][0], 2.0)
        self.assertAlmostEqual(report['span_delta'], 0.0, places=3)
        self.assertAlmostEqual(report['luma_median_delta'], 0.0, places=3)
        self.assertTrue(report['within_tolerance'])

    def test_no_overlap_is_reported(self):
        provided = dict(video=[dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(10)],
                        audio=[])
        measured = [dict(pts=100.0 + t * 0.1, mean=100.0, scene=1.0) for t in range(10)]
        report = cm_features.compare(provided, measured, [])
        self.assertIn('skipped', report)
        self.assertNotIn('within_tolerance', report)

    def test_shifted_content_is_rejected(self):
        # The sideband is two seconds off: the shared window then compares
        # different pictures, which the values and the span both show.
        provided = dict(video=[dict(pts=2.0 + t * 0.1, mean=180.0 if t < 15 else 100.0, scene=1.0)
                               for t in range(20)],
                        audio=[dict(pts=2.0, rms_db=-30.0)])
        measured = [dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(40)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertGreater(report['mean_luma_delta'], 2.0)
        self.assertFalse(report['within_tolerance'])

    def test_capture_shorter_than_the_media_is_rejected(self):
        # The capture stops early, so it cannot describe the whole programme.
        provided = dict(video=[dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(10)],
                        audio=[dict(pts=0.0, rms_db=-30.0)])
        measured = [dict(pts=t * 0.1, mean=100.0, scene=1.0) for t in range(40)]
        report = cm_features.compare(provided, measured, [dict(pts=0.0, rms_db=-30.0)])
        self.assertLess(report['coverage_ratio'], 0.95)
        self.assertFalse(report['within_tolerance'])

if __name__ == '__main__':
    unittest.main()


class AlignAudioTest(unittest.TestCase):

    def _parsed(self, video_first, audio_pts):
        return dict(video=[dict(pts=video_first, mean=100.0, scene=1.0),
                           dict(pts=video_first + 1.0, mean=100.0, scene=1.0)],
                    audio=[dict(pts=p, rms_db=-30.0, samples=1024) for p in audio_pts],
                    meta={})

    def test_rows_before_the_video_are_dropped(self):
        parsed = self._parsed(2.002, [-0.015, 0.5, 2.1, 2.5])
        cm_features.align_audio(parsed)
        self.assertEqual([round(r['pts'], 3) for r in parsed['audio']], [2.1, 2.5])
        self.assertEqual(parsed['meta']['audio_dropped'], 2)

    def test_rows_are_not_shifted(self):
        parsed = self._parsed(2.002, [2.1, 2.5])
        cm_features.align_audio(parsed)
        self.assertEqual([round(r['pts'], 3) for r in parsed['audio']], [2.1, 2.5])
        self.assertNotIn('audio_dropped', parsed['meta'])

    def test_nothing_dropped_when_already_aligned(self):
        parsed = self._parsed(0.0, [0.0, 0.5])
        cm_features.align_audio(parsed)
        self.assertNotIn('audio_dropped', parsed['meta'])

